CREATE TABLE policy_document (
 id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
 policy_type VARCHAR(30) NOT NULL CHECK(policy_type IN ('TERMS','PRIVACY')),
 version_number INTEGER NOT NULL,
 title VARCHAR(180) NOT NULL,
 body_markdown TEXT NOT NULL,
 status VARCHAR(20) NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','PUBLISHED','RETIRED')),
 published_at TIMESTAMPTZ,
 created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
 created_by UUID REFERENCES app_user(id),
 UNIQUE(policy_type,version_number)
);
INSERT INTO policy_document(policy_type,version_number,title,body_markdown,status,published_at)
VALUES
('TERMS',1,'Terms and Conditions - Review Draft',
'# Terms and Conditions\n\n**Important:** This initial text is a product draft and must be reviewed by qualified counsel for the operating jurisdiction before accepting customers.\n\n## Service and publication\nThe service provides tools to create and publish digital invitations. A paid invitation is hosted only for the validity period shown at checkout. Unless a different policy is displayed and accepted at purchase, the invitation remains active until the last scheduled function date plus seven calendar days. The effective grace period is configurable and the agreed value is stored with the purchase. The service does not promise lifetime hosting. Extensions may be offered separately.\n\n## Customer content and permissions\nYou are responsible for the accuracy, legality and permissions for names, photographs, addresses, venue details and other material you submit. Do not upload content you do not have the right to use. You must not upload unlawful, abusive, infringing or harmful material.\n\n## Privacy and public links\nDrafts and account information are private. When you explicitly publish, the selected invitation content becomes accessible to people who have its unique link. Do not include information you intend to keep confidential. Payment and account details are not part of the public invitation.\n\n## Payments, expiry and availability\nPrices, taxes, validity, extension options and applicable terms are displayed before purchase. After expiry, the public invitation may show an expired page or become unavailable. Expiry does not mean immediate deletion; retention is governed by the Privacy Policy and legal obligations.\n\n## Providers and limitations\nPayment, storage, email and infrastructure providers may process data to provide the service. The platform uses reasonable safeguards but no internet service can guarantee absolute security or uninterrupted availability.\n\n## Suspension and support\nWe may restrict access to address security, abuse, legal or operational issues. Contact details and support channels must be published by the operator before launch.\n\n## Changes and governing terms\nMaterial policy changes are versioned. The terms accepted for a purchase are recorded with that transaction. Applicable law, dispute handling and operator identity must be completed by the service operator before launch.',
'PUBLISHED',now()),
('PRIVACY',1,'Privacy Policy - Review Draft',
'# Privacy Policy\n\n**Important:** This initial text is a product draft. The operator must complete its identity, contact details, retention schedule, legal basis and jurisdiction-specific disclosures with qualified counsel before launch.\n\n## Information we process\nWe may process account details, contact information, invitation drafts, event dates, uploaded media, consent records, device and security logs, and payment references. Full card credentials are handled by the payment provider and should not be stored by this platform.\n\n## Purpose and sharing\nInformation is used to operate accounts, create invitations, process payments, store and deliver selected content, provide support, prevent abuse, secure the service and meet legal obligations. Service providers may process information on our behalf under appropriate arrangements. We do not sell customer personal information to unrelated parties for their independent marketing.\n\n## Private and published information\nDrafts, account information and payment records are private. Only content selected for publication is exposed through the invitation link. A published link may be forwarded by its recipient; do not publish sensitive personal information.\n\n## Security and retention\nWe use reasonable technical and organizational safeguards. No method of transmission or storage is completely secure. Data is retained only as needed for service delivery, account support, security, financial records and legal requirements, subject to applicable retention obligations. Expiry of an invitation does not automatically erase all related records.\n\n## Your choices and requests\nSubject to applicable law, you may request access, correction, export or deletion of personal information by contacting the service operator. Certain records may need to be retained for legal, fraud-prevention or accounting purposes.\n\n## Children and contact\nThe operator must publish an appropriate age policy and privacy contact before launch. Do not submit personal data about another person unless you have a lawful basis and any required permission.\n\n## Updates\nPolicy versions and effective dates are recorded. Material changes will be communicated where required by law.',
'PUBLISHED',now())
ON CONFLICT(policy_type,version_number) DO NOTHING;

INSERT INTO system_setting(setting_key,setting_value,value_type,description)
VALUES ('consent.required.privacy','true'::jsonb,'BOOLEAN','Customer accepts the applicable Privacy Policy')
ON CONFLICT(setting_key) DO NOTHING;
